// Verifica a trava GLOBAL (Data Table "automation_lock", linha lock_name="global").
// Impede que os workflows 1/2/3 rodem ao mesmo tempo (worker/sessao unicos).

const LOCK_TIMEOUT_MINUTES = 30;

const row = $input.first().json;
const status = row.status || "idle";
const lockedAt = row.locked_at || "";

if (status === "running" && lockedAt) {
  const lockAgeMinutes = (Date.now() - new Date(lockedAt).getTime()) / 60000;
  if (!isNaN(lockAgeMinutes) && lockAgeMinutes < LOCK_TIMEOUT_MINUTES) {
    return []; // outro workflow esta rodando -- para aqui, nada foi adquirido
  }
  // trava velha demais (execucao anterior travou sem liberar) -- segue e assume
}

return [{ json: { proceed: true } }];

// Transforma o array de issues em itens individuais do n8n, um por issue.
// Se nao houver nenhuma issue, sinaliza explicitamente para liberar a trava global.

const response = $input.first().json;
const issues = response.issues || [];

if (issues.length === 0) {
  return [{ json: { no_eligible_tickets: true } }];
}

return issues.map((issue) => ({ json: { id: issue.id } }));

// Seleciona UM chamado elegivel por execucao (o worker processa um por vez,
// protegido pela trava global) e prepara o payload para o worker.
//
// Elegivel = status "Waiting for Development" (15), colocado MANUALMENTE por
// um humano depois de revisar e aprovar os artefatos do Workflow 1. Esse
// status substitui o antigo campo customizado "Artifacts Approved?".
//
// Nunca retorna lista vazia: se nenhum chamado for valido, retorna
// { valid: false }, para que a trava global seja liberada.

const PROJECT_NAME = "NOME_DO_SEU_PROJETO_NO_LOVABLE";
const STATUS_WAITING_FOR_DEVELOPMENT = 15;
const AUTOMATION_NOTE_PREFIX = "Resultado automatizado do Workflow";
const REVIEW_NOTE_PREFIX = "Resultado automatizado do Workflow 3";

for (const item of $input.all()) {
  const issue = item.json.issue;
  if (!issue || !issue.status || issue.status.id !== STATUS_WAITING_FOR_DEVELOPMENT) continue;

  const journals = issue.journals || [];
  const customFields = issue.custom_fields || [];

  // Contador de tentativas (campo id 6): zerado pelo Workflow 1 a cada novo
  // snapshot de requisitos, incrementado pelo Workflow 2 a cada tentativa.
  const attemptsField = customFields.find((f) => f.id === 6);
  const devAttempts = attemptsField && attemptsField.value
    ? (parseInt(attemptsField.value, 10) || 0)
    : 0;

  // Fonte principal dos requisitos: snapshot consolidado do Workflow 1 (campo id 5).
  let requirementsText = null;
  const snapshotField = customFields.find((f) => f.id === 5);
  if (snapshotField && snapshotField.value) {
    try {
      const snapshot = JSON.parse(snapshotField.value);
      const lines = [];
      if (snapshot.user_story) lines.push(`User Story: ${snapshot.user_story}`);
      if (snapshot.summary) lines.push(``, `Resumo: ${snapshot.summary}`);
      if (Array.isArray(snapshot.acceptance_criteria) && snapshot.acceptance_criteria.length) {
        lines.push(``, `Critérios de aceite:`, ...snapshot.acceptance_criteria.map((c) => `- ${c}`));
      }
      if (Array.isArray(snapshot.development_tasks) && snapshot.development_tasks.length) {
        lines.push(``, `Tarefas de desenvolvimento:`, ...snapshot.development_tasks.map((t) => `- ${t}`));
      }
      if (Array.isArray(snapshot.system_modules_affected) && snapshot.system_modules_affected.length) {
        lines.push(``, `Módulos afetados: ${snapshot.system_modules_affected.join(", ")}`);
      }
      requirementsText = lines.join("\n").trim();
    } catch (e) {
      requirementsText = null;
    }
  }

  // Fallback para chamados antigos, sem snapshot: ultima nota humana.
  if (!requirementsText) {
    const humanNotes = journals.filter(
      (j) => j.notes && j.notes.trim().length > 0 && !j.notes.trim().startsWith(AUTOMATION_NOTE_PREFIX)
    );
    requirementsText = humanNotes.length ? humanNotes[humanNotes.length - 1].notes : null;
  }

  if (!requirementsText) continue;

  // Feedback da ultima revisao reprovada (Workflow 3), se for um retrabalho.
  const reviewNotes = journals.filter(
    (j) => j.notes && j.notes.trim().startsWith(REVIEW_NOTE_PREFIX)
  );
  const previousReviewFeedback = reviewNotes.length
    ? reviewNotes[reviewNotes.length - 1].notes
    : null;

  return [
    {
      json: {
        valid: true,
        issue_id: issue.id,
        project_name: PROJECT_NAME,
        title: issue.subject,
        requirements: requirementsText,
        previous_review_feedback: previousReviewFeedback,
        dev_attempts: devAttempts,
      },
    },
  ];
}

return [{ json: { valid: false } }];

// Limite de tentativas de desenvolvimento atingido -- interrompe a automacao
// e pede verificacao manual (protecao contra loop Workflow 2 <-> Workflow 3
// e contra gasto descontrolado de cota).

const MAX_ATTEMPTS = 3; // mantenha igual ao valor do IF "Verificar Limite de Tentativas"

const item = $input.first().json;

const notesLines = [
  `Resultado automatizado do Workflow 2 (Claude Code + Lovable MCP):`,
  ``,
  `Limite de ${MAX_ATTEMPTS} tentativas de desenvolvimento atingido sem sucesso (Development Attempts = ${item.dev_attempts}).`,
  `A automação foi interrompida propositalmente -- revisão manual necessária antes de continuar.`,
  ``,
  `Para retomar: verifique o histórico de notas de revisão do Workflow 3 nesta issue, corrija ` +
    `manualmente o que for necessário (ou ajuste os requisitos), redefina o campo ` +
    `"Development Attempts" para 0, e mude o status para "Waiting for Development".`,
];

return [
  {
    json: {
      issue_id: item.issue_id,
      status_id: 11, // Automation Error
      notes: notesLines.join("\n"),
      custom_fields: [],
    },
  },
];

// Interpreta a resposta do worker (ou a falha da chamada) e monta a
// atualizacao do Redmine. Incrementa o contador de tentativas (campo id 6).
//
// O node "Chamar Worker" esta configurado para continuar em caso de erro:
// se o worker falhar (ex: sessao OAuth expirada, timeout), o chamado vai
// para "Automation Error" com o erro na nota, em vez de ficar preso em
// "Under Development".

const STATUS_MAP = {
  "New": 1,
  "Under Analysis": 2,
  "Artifacts Generated": 3,
  "Waiting for Artifact Approval": 4,
  "Under Development": 5,
  "Waiting for Tests": 6,
  "Under Testing": 7,
  "Waiting for Tests Approval": 8,
  "Ready for Publishing": 9,
  "Published": 10,
  "Automation Error": 11,
  "Waiting for Answers": 13,
  "Questions Answered": 14,
  "Waiting for Development": 15,
};

const payload = $('Filtrar e Preparar Payload').item.json;
const issueId = payload.issue_id;
const worker = $input.first().json;

let workerError = null;
if (worker.error) {
  workerError = typeof worker.error === "string"
    ? worker.error
    : (worker.error.message || JSON.stringify(worker.error));
}

const success = !workerError && worker.success === true;
const summary = worker.summary || "(sem summary retornado pelo worker)";
const changedFiles = Array.isArray(worker.changed_files) ? worker.changed_files : [];
const diffSummary = worker.diff_summary || "";
const warnings = Array.isArray(worker.warnings) ? worker.warnings : [];
const nextStatusName = worker.next_recommended_status || null;

let statusId = (!workerError && nextStatusName) ? STATUS_MAP[nextStatusName] : undefined;
if (statusId === undefined || statusId === null) {
  statusId = success ? STATUS_MAP["Waiting for Tests"] : STATUS_MAP["Automation Error"];
}
// "Under Development" e "Waiting for Development" nunca sao destinos validos
// ao fim do Workflow 2 (evita o chamado ficar preso ou entrar em loop).
if (statusId === STATUS_MAP["Under Development"] || statusId === STATUS_MAP["Waiting for Development"]) {
  statusId = success ? STATUS_MAP["Waiting for Tests"] : STATUS_MAP["Automation Error"];
}

const notesLines = [
  `Resultado automatizado do Workflow 2 (Claude Code + Lovable MCP):`,
  ``,
  `Sucesso: ${success}`,
];

if (workerError) {
  notesLines.push(`Erro ao chamar o worker: ${workerError}`);
} else {
  notesLines.push(`Resumo: ${summary}`);
}
if (changedFiles.length) {
  notesLines.push(``, `Arquivos alterados:`, ...changedFiles.map((f) => `- ${f}`));
}
if (diffSummary) {
  notesLines.push(``, `Diff: ${diffSummary}`);
}
if (warnings.length) {
  notesLines.push(``, `Avisos:`, ...warnings.map((w) => `- ${w}`));
}

const newAttempts = (payload.dev_attempts || 0) + 1;
notesLines.push(``, `Tentativa de desenvolvimento nº ${newAttempts}.`);

return [
  {
    json: {
      issue_id: issueId,
      status_id: statusId,
      notes: notesLines.join("\n"),
      custom_fields: [{ id: 6, value: String(newAttempts) }],
    },
  },
];
